GuideManager = {}
local this = GuideManager;

function GuideManager.CloseHelp()
    LobbyView.Instance():ShowLeisureHelp(false);
    LobbyView.Instance():ShowHighLadderHelp(false);
    LobbyView.Instance():ShowStoryHelp(false);

    MainUIView.Instance():ShowHeroHelp(false);
    MainUIView.Instance():ShowDeckHelp(false);
    MainUIView.Instance():ShowBagHelp(false);
end

function GuideManager.CheckHelp()
    this.CloseHelp();
    local level = Player.GetLevel();
    if level >= 8 then
        return;
    end
    if level == 1 then
        LobbyView.Instance():ShowLeisureHelp(true);
    elseif level == 2 then
        LobbyView.Instance():ShowHighLadderHelp(true);
    elseif level == 3 then
        LobbyView.Instance():ShowStoryHelp(true);
    elseif level == 4 or level == 5 then
        local chestNum = ChestManager.GetChestCount(3011);
        if chestNum > 0 then
            MainUIView.Instance():ShowBagHelp(true);
        else
            local deckNum = DeckLineupManager.GetLineupNum();
            if deckNum < 2 then
                MainUIView.Instance():ShowDeckHelp(true);
            end
        end
    elseif level >= 6 then
        local heroUpgrade =  HeroManager.GetHerosUpgrade();
        if heroUpgrade ~= true then
            MainUIView.Instance():ShowHeroHelp(true);
        end
    end
end